package com.ajay.amusezone.controller;
import com.ajay.amusezone.dto.BookingRequest; import com.ajay.amusezone.entity.Booking; import com.ajay.amusezone.service.BookingService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/bookings") public class BookingController {private final BookingService s; public BookingController(BookingService s){this.s=s;} @PostMapping public Booking create(@Valid @RequestBody BookingRequest r){return s.create(r);} @GetMapping public List<Booking> all(){return s.all();} @GetMapping("/user/{userId}") public List<Booking> byUser(@PathVariable Long userId){return s.byUser(userId);} @GetMapping("/{id}") public Booking get(@PathVariable Long id){return s.get(id);} @PutMapping("/{id}/cancel") public Booking cancel(@PathVariable Long id){return s.cancel(id);}}
